;-----------------------------------------------------------;; Equates for Control TypessimpleButtonControl	equ $80000000checkControl	equ $82000000radioControl	equ $84000000scrollBarControl	equ $86000000growControl	equ $88000000statTextControl	equ $81000000LineEditControl	equ $83000000TextEditControl	equ $85000000popUpControl	equ $87000000listControl	equ $89000000iconButtonControl	equ $8B000000pictureControl	equ $8D000000;-----------------------------------------------------------;; New action messages supported by some controls;ctlHandleEvent	equ 13	13 Send the event record to controlctlChangeActivity	equ 14	14 The activity bit in MoreFlags just changed.ctlChangeBounds	equ 15ctlWindChangeSize   equ 16ctlHandleTab	equ 17ctlNotifyMultiPart	equ 18	18 Called if set and when HideControl is calledctlWinStateChange	equ 19	Called if window state changes.;-----------------------------------------------------------;; New Error codes for control manager.;NoCtlError	equ $1004	no controls in windowNoSuperCtlError 	equ $1005	no super controls in windowNoCtlActiveError	equ $1006	no active super controlNotSuperCtlError	equ $1007	action can only be done on super controlCanNotBeActiveError	equ $1008	This control cannot be made activeNoSuchIDError	equ $1009	The specified ID cannot be foundTooFewParmsError	equ $100A	;there were not enough parameters specified.NoCtlToBeActiveError equ $100B	Tried to make next ctl active, but no ctls could be active.NoWind_Err	equ $100C	There is no front window.;-----------------------------------------------------------;; MoreFlags Bit Definitions;FCtlActive	equ $8000FCtlCanBeActive	equ $4000FCtlWantEvents	equ $2000FCtlProcRefNotPtr	equ $1000FctlTellAboutGrow	equ $0800FctlIsMultiPart	equ $0400TitleVerbMask	equ %00000011ColorTableVerbMask	equ %00001100IVVerbMask	equ %00000011TitleIsPtr	equ 0TitleIsHandle	equ 1TitleIsResource	equ 2ColorTableIsPtr	 equ %00000000ColorTableIsHandle	 equ %00000100ColorTableIsResource equ %00001000IVIsPtr	equ 0IVIsHandle	equ 1IVIsResource	equ 2;-----------------------------------------------------------;; Flag bit definitions for StatText Controls;FSubstituteText	equ $0002	; Bit is set to indicate that text must be substitutedFSubTextType	equ $0001	; Bit is set to indicate PStrings, clear for Cstrings		;  (bit is sent to compile text as is.);---------------------------------------------------------------; these are the verbs that NewControl2 supports:;---------------------------------------------------------------singlePtr	equ  0singleHandle	equ  1singleResource	equ  2ptrToPtr	equ  3ptrToHandle	equ  4ptrToResource	equ  5handleToPtr	equ  6handleToHandle	equ  7handleToResource	equ  8resourceToResource	equ  9NewCtlRecord	RECORD  0;---------------------------------------------------------------ctlNext	ds.l  1ctlOwner	ds.l  1ctlRect	ds.w  4ctlFlag	ds.b  1ctlHilite	ds.b  1ctlValue	ds.w  1ctlProc	ds.l  1ctlAction	ds.l  1ctlData	ds.l  1ctlRefCon	ds.l  1ctlColor	ds.l  1ctlReserved	ds.b  16ctlID	ds.L  1ctlMoreFlags	ds.w  1ctlVersion	ds.w  1;---------------------------------------------------------------ctlSize;---------------------------------------------------------------ctlKey1	equ ctlReservedctlKey2	equ ctlKey1+1ctlKeyMods	equ ctlKey2+1ctlKeyModsCareBits	equ ctlKeyMods+2ctlJust	equ ctlReserved	ENDRMINTEMPLATEPCOUNT	equ 6;-----------------------------------------------------------;; This is the generic template record.  All templates have; these fields in them.;TemplateRecord	RECORD  0pCount	ds.w  1	;parameter count (must be at least 6)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;Ref to DefProc, determines control typeFlags	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application defined	ENDR;-----------------------------------------------------------;; This is the generic template record.  All templates have; these fields in them.;CustomTemplate	RECORD  0pCount	ds.w  1	;parameter count (must be at least 8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;Ref to DefProc, determines control typeFlags	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application defineddefProcDATA	ds.b  1	ENDR;-----------------------------------------------------------;; This is the template for simpleButtonControl.;simpleButtonTemplate RECORD  0pCount	ds.w  1	;parameter count (7 or 8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;simpleButtonControl = $80000000Flag	ds.w  1	;low 2 bits refer to button typeMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.L  1	;Pointer, Handle or resourceIDColorTableRef	ds.L  1	;Optional Pointer, Handle or resourceIDKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.	ENDR;-----------------------------------------------------------;; This is the template for checkControl.;checkTemplate 	RECORD  0pCount	ds.w  1	;parameter count (8 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;checkControl = $82000000Flag	ds.w  1	;nothing specialMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.L  1	;Pointer, Handle or resourceIDValue	ds.w  1	;Initial state of check boxColorTableRef	ds.L  1	;Optional Pointer, Handle or resourceIDKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.	ENDR;-----------------------------------------------------------;; This is the template for radioControl.;radioTemplate	RECORD  0pCount	ds.w  1	;parameter count (8 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;radioControl = $84000000Flag	ds.w  1	;bits 0-6 are family numberMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.L  1	;Pointer, Handle or resourceIDValue	ds.w  1	;Initial state of radio buttonColorTableRef	ds.L  1	;Optional Pointer, Handle or resourceIDKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.	ENDR;-----------------------------------------------------------;; This is the template for statTextControl.;StatTextTemplate	RECORD  0pCount	ds.w  1	;parameter count (7, 8 or 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;StatTextControl = $81000000Flag	ds.w  1	;low 2 bits refer to TextRefMoreFlags	ds.w  1	;must be 0RefCon	ds.l  1	;application definedTextRef	ds.L  1	;Pointer, Handle or resourceIDTextSize	ds.w  1	;If text is ref'ed by ptr this is validJust	ds.w  1	;Initial justification word to be passed to LETextBox2	ENDR;-----------------------------------------------------------;; This is the template for LineEdit controls;LineEditTemplate	RECORD  0pCount	ds.w  1	;parameter count (8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;LineEditControl = $83000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application definedMaxLen	ds.w  1	;maximum length of input lineIVRef	ds.L  1	;Reference to initial value	ENDR;-----------------------------------------------------------;; This is the template for Picture controls.;PictureTemplate	RECORD  0pCount	ds.w  1	;parameter count (7)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;PictureControl = $8D000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedPicRef	ds.L  1	;handle or resource	ENDR;-----------------------------------------------------------;; This is the template for Scroll Controls;ScrollTemplate	RECORD  0pCount	ds.w  1	;parameter count (8 or 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;ScrollControl = $86000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedDataSize	ds.w  1	;amount of data represented by the scroll barViewSize	ds.w  1	;amount of data seen at one timeInitialThumb	ds.w  1	;initial setting of the thumb.ColorRef	ds.L  1	;Reference to color table	ENDR;-----------------------------------------------------------;; This is the template for Scroll Controls;GrowTemplate	RECORD  0pCount	ds.w  1	;parameter count (6 or 7)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;GrowControl = $88000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedColorRef	ds.L  1	;Reference to color table	ENDR;-----------------------------------------------------------;; This is the template for List Controls;ListTemplate	RECORD  0pCount	ds.w  1	;parameter count (14 or 15)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.L  1	;ListControl = $89000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;RefCon	ds.l  1	;application definedListSize	ds.w  1	;num members in listListView	ds.w  1	;num members seen at one timeListType	ds.w  1	;multi-selections, pascal strings etcListStart	ds.w  1	;First member to be seenListDraw	ds.L  1	;member drawing routineListMemHeight	ds.w  1	;height of each itemListMemSize	ds.w  1	;num bytes in list recordListRef	ds.L  1	;ref to list of member recordsColorRef	ds.L  1	;Reference to color table	ENDR;-----------------------------------------------------------;; Extended task record def;NewTaskRecord	Record 0taskWhat   	ds.W 1	EQU   $00 ; Word - WmTaskRec -  taskMessage   	ds.L 1	EQU   $02 ; Long - WmTaskRec -  taskWhen   	ds.L 1	EQU   $06 ; Long - WmTaskRec -  taskWhere   	ds.L 1	EQU   $0A ; Point - WmTaskRec -  taskModifiers   	ds.W 1	EQU   $0E ; Word - WmTaskRec -  taskData   	ds.L 1	EQU   $10 ; Long - WmTaskRec - TaskMaster return value.taskMask   	ds.L 1	EQU   $14 ; Long - WmTaskRec - TaskMaster feature mask.taskLastClick	ds.L 1taskClickCount	ds.W 1taskData2	ds.L 1taskData3	ds.L 1taskData4	ds.L 1	ENDRSuperCtlSize	equ NewCtlRecord.ctlSizeMaxMessages	equ 13;-----------------------------------------------------------;; Resource Type Definitions;rIcon	equ $8001rPicture	equ $8002rControlList	equ $8003rControlTemplate	equ $8004rWindow	equ $8005rString	equ $8006rStringList	equ $8007rMenuBar	equ $8008rMenu	equ $8009rMenuItem	equ $800ArTextForLETextBox2	equ $800BrCtlDefProc	equ $800CrCtlColorTable	equ $800D